"""Audit Trail Markdown Visitor."""

from src.visitors.i_evaluation_visitor import IEvaluationVisitor
from src.models.trace_evaluation import TraceEvaluation
from src.models.evaluation_summary import EvaluationSummary
from src.models.evaluation_batch_result import EvaluationBatchResult


class AuditTrailVisitor(IEvaluationVisitor):
    """Generates an executive compliance and audit trail document with full factual rationales."""

    def __init__(self):
        self._lines = [
            "# Workplace AI Agent Compliance & Audit Trail",
            "",
            "Generated by StackGen AI Governance Pipeline.",
            ""
        ]

    def visit_summary(self, summary: EvaluationSummary) -> None:
        self._lines.extend([
            "## Executive Summary",
            "",
            f"- **Evaluated Traces**: {summary.total_traces}",
            f"- **Pass Rate**: {summary.pass_rate:.1%}",
            f"- **Release Blockers**: {summary.total_release_blockers}",
            ""
        ])

    def visit_trace(self, trace_eval: TraceEvaluation) -> None:
        icon = "[PASS]" if trace_eval.result.value == "pass" else "[FAIL]"
        rb_badge = "CRITICAL RELEASE BLOCKER" if trace_eval.is_release_blocker else "Standard Check"
        self._lines.extend([
            f"### {icon} Trace {trace_eval.trace_id} ({rb_badge})",
            f"- **Evaluator**: `{trace_eval.evaluator_type.value}`",
            f"- **Category**: `{trace_eval.release_blocker_category.value}`"
        ])
        if trace_eval.reasons:
            self._lines.append("- **Reasons**:")
            for r in trace_eval.reasons:
                self._lines.append(f"  - {r}")
        if trace_eval.driving_facts:
            self._lines.append("- **Driving Facts**:")
            for f in trace_eval.driving_facts:
                self._lines.append(f"  - {f}")
        self._lines.append("")

    def visit_batch(self, batch: EvaluationBatchResult) -> None:
        self.visit_summary(batch.summary)
        self._lines.append("## Trace Trajectory Decisions\n")
        for t in batch.traces:
            self.visit_trace(t)

    def get_output(self) -> str:
        return "\n".join(self._lines)
